def gen(rng):
    def make(n, k, lo, hi, dup=False):
        if dup:
            a = sorted(rng.randint(lo, min(hi, lo + 3)) for _ in range(n))
        else:
            a = sorted(rng.randint(lo, hi) for _ in range(n))
        b = []
        i = 0
        while i < n:
            blk = a[i:i + k + 1]
            rng.shuffle(blk)
            b.extend(blk)
            i += k + 1
        return b
    def fmt(n, k, arr):
        return f'{n} {k}\n' + ' '.join(map(str, arr))
    tests = [fmt(1, 0, [7]), fmt(2, 1, [2, 1]), fmt(3, 2, [3, 2, 1]), fmt(4, 0, [-5, -5, 0, 9]), fmt(5, 1, [2, 1, 4, 3, 5]), fmt(7, 2, [3, 1, 2, 6, 4, 5, 7])]
    for n in (3, 5, 8, 10, 15, 20, 30):
        for _ in range(3):
            k = rng.randint(0, n - 1)
            tests.append(fmt(n, k, make(n, k, -50, 50)))
    for n in (6, 12, 20):
        k = rng.randint(1, n - 1)
        tests.append(fmt(n, k, make(n, k, 0, 3, True)))
    n = 100000
    for k in (1, 50, 1000):
        tests.append(fmt(n, k, make(n, k, -10 ** 9, 10 ** 9)))
    tests.append(fmt(n, n - 1, make(n, n - 1, -10 ** 9, 10 ** 9)))
    return tests

